INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob jedes IT-Projekt öffentliche Ausschreibungen erfordert?', 2, '[{"text": "Nein", "correct": true, "because": "Nur bei öffentlichen Aufträgen"}, {"text": "Ja", "correct": false, "because": "Private Projekte frei wählbar"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Prinzip ist bei der Vergabe von IT-Dienstleistungen entscheidend?', 3, '[{"text": "Wettbewerbsfreiheit", "correct": true, "because": "Fördert faire Anbieterauswahl"}, {"text": "Höchster Preis", "correct": false, "because": "Nicht zwingend"}, {"text": "Schnellste Lieferung", "correct": false, "because": "Kein Rechtsfaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken sind bei der Anbieterauswahl für IT-Projekte verboten?', 5, '[{"text": "Absprachen zwischen Bietern", "correct": true, "because": "Verstoßen gegen Wettbewerbsrecht"}, {"text": "Exklusive Verträge", "correct": true, "because": "Können Markt beschränken"}, {"text": "Qualitätsprüfung", "correct": false, "because": "Legale Anforderung"}, {"text": "Vertragsverhandlungen", "correct": false, "because": "Teil des Prozesses"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Preisabsprachen sind illegal. b) Jeder Anbieter muss gewinnen.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "b) widerspricht fairer Vergabe"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich, wenn ich eine Ausschreibung für Software erstelle?', 4, '[{"text": "Transparenz", "correct": false, "because": "Fördert faire Auswahl"}, {"text": "Leistungsbeschreibung", "correct": false, "because": "Definiert Anforderungen"}, {"text": "Bürogestaltung", "correct": true, "because": "Kein Vergabefaktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass kleine IT-Firmen nie öffentliche Aufträge bekommen. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Alle können bieten"}, {"text": "Ja", "correct": false, "because": "Wettbewerb offen für alle"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten verstößt gegen das Vergaberecht?', 3, '[{"text": "Geheime Absprachen", "correct": true, "because": "Untergräbt fairen Wettbewerb"}, {"text": "Qualitätskontrolle", "correct": false, "because": "Legale Praxis"}, {"text": "Vertragsgestaltung", "correct": false, "because": "Teil des Prozesses"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Faktoren fördern eine rechtssichere Ausschreibung?', 5, '[{"text": "Klare Kriterien", "correct": true, "because": "Ermöglichen objektive Bewertung"}, {"text": "Öffentliche Bekanntmachung", "correct": true, "because": "Gewährleistet Zugang"}, {"text": "Persönliche Präferenzen", "correct": false, "because": "Verzerren Auswahl"}, {"text": "Geheime Verhandlungen", "correct": false, "because": "Verstoßen gegen Regeln"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass a) Vergaben diskriminierungsfrei sein müssen und b) immer der billigste Anbieter gewinnt. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Qualität zählt, nicht nur Preis"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für eine rechtssichere IT-Vergabe?', 4, '[{"text": "Nachvollziehbare Bewertung", "correct": false, "because": "Sichert Fairness"}, {"text": "Veröffentlichung", "correct": false, "because": "Fördert Transparenz"}, {"text": "Firmenfarben", "correct": true, "because": "Kein rechtlicher Aspekt"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist ein Monopol in der IT erlaubt?', 2, '[{"text": "Nein", "correct": true, "because": "Schadet Wettbewerb"}, {"text": "Ja", "correct": false, "because": "Rechtlich eingeschränkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Praktiken sichern einen fairen Wettbewerb?', 4, '[{"text": "Offene Ausschreibungen", "correct": true, "because": "Ermöglichen breite Teilnahme"}, {"text": "Transparente Kriterien", "correct": true, "because": "Verhindern Bevorzugung"}, {"text": "Exklusive Vereinbarungen", "correct": false, "because": "Beschränken Wettbewerb"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Wettbewerbsregeln nur für große Firmen gelten. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Gelten für alle Marktteilnehmer"}, {"text": "Ja", "correct": false, "because": "Umfassende Anwendung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich bei der Ausschreibung eines IT-Projekts?', 3, '[{"text": "Beste Leistung zum fairen Preis", "correct": true, "because": "Optimiert Qualität und Kosten"}, {"text": "Schnellste Umsetzung", "correct": false, "because": "Nicht allein entscheidend"}, {"text": "Maximale Anbieteranzahl", "correct": false, "because": "Kein primäres Ziel"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Kartelle sind verboten. b) Rabatte sind immer illegal.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Rabatte sind legal"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rolle spielt die Dokumentation in einer Ausschreibung?', 4, '[{"text": "Nachvollziehbarkeit sichern", "correct": true, "because": "Schützt vor Streitigkeiten"}, {"text": "Schnellere Abwicklung", "correct": false, "because": "Nicht primäres Ziel"}, {"text": "Marketingzwecke", "correct": false, "because": "Kein rechtlicher Faktor"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob ein Bieter mit niedrigstem Preis immer gewinnt?', 2, '[{"text": "Nein", "correct": true, "because": "Qualität und Kriterien zählen"}, {"text": "Ja", "correct": false, "because": "Andere Faktoren relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Verhalten fördert einen fairen IT-Markt?', 5, '[{"text": "Offene Vergaben", "correct": true, "because": "Fördern Wettbewerb"}, {"text": "Transparente Prozesse", "correct": true, "because": "Verhindern Absprachen"}, {"text": "Geheime Verträge", "correct": false, "because": "Schaden Fairness"}, {"text": "Einzelanbieter", "correct": false, "because": "Beschränken Auswahl"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist es legal, Mitbewerber auszuschließen?', 3, '[{"text": "Nein", "correct": true, "because": "Verstößt gegen Wettbewerbsrecht"}, {"text": "Ja", "correct": false, "because": "Nur bei objektiven Gründen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Kriterium ist bei der Anbieterauswahl unwichtig?', 3, '[{"text": "Erfahrung", "correct": false, "because": "Zeigt Kompetenz"}, {"text": "Kostenvoranschlag", "correct": false, "because": "Beeinflusst Budget"}, {"text": "Firmengröße", "correct": true, "because": "Kein direkter Leistungsindikator"}]');
